import{z as i,x as o,o as B,c as d,q as t,j as n,D as A,d as a,s as r,S as s,b as e}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"增量更新与一致性","description":"","frontmatter":{"title":"增量更新与一致性","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/rag-incremental-consistency.md","filePath":"llm/rag-incremental-consistency.md","lastUpdated":1791063341000}'),p={name:"llm/rag-incremental-consistency.md"};function D(m,E,F,c,C,h){const l=o("Mermaid");return B(),d("div",null,[E[2]||(E[2]=t('<h1 id="增量更新与一致性" tabindex="-1">增量更新与一致性 <a class="header-anchor" href="#增量更新与一致性" aria-label="Permalink to &quot;增量更新与一致性&quot;">​</a></h1><div class="epigraph"><p>索引不是建完就完的资产，是随语料呼吸的系统；一致性不是让所有副本时刻相同，是让「哪些版本在一起」永远可回答。</p><footer>—— 据索引版本化与检索运维工程实践整理</footer></div><p><a href="/llm/rag-latency-cost">上一课</a>把延迟与成本压进预算，缓存与降级都进了账本。本课处理时间维度：语料天天变——文档改一段、加一节、删一页，索引怎么跟上，各版本怎么对齐，旧答案怎么下线。第一课说过「换切分即数据迁移」；生产里这种迁移每天在发生，只是没人叫它迁移。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>三重一致性缺口。索引内：文档重写后哪些块保留原 ID、哪些重嵌——块 ID 一变，引用、缓存、权限过滤全部跟着断。跨通道：BM25 删了、向量还在（或反之），已撤回文档仍从另一路漏出——这不是陈旧的性能问题，是权限与合规事故。跨版本：嵌入模型、切分器、融合权重、重排器各自演进，线上一个请求穿过不同版本组合，评测环境与线上不可比，改动前后的三角分数没法归因。三重缺口共同的根源：没有「版本三元组」的意识——切分版本、嵌入版本、分析器版本必须作为一个整体被记录和切换。</p><p><span class="marginnote">术语翻译：墓碑（tombstone）就是「先立牌子、后拆房子」的删除方式——删请求只打一个「已删」标记，等所有通道都确认读到标记，才异步真正清数据。好处是删除命令超时或部分失败时，漏出旧内容的问题仍然可发现、可重试。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>版本三元组加配置版本，写进索引卡，任何一维变更触发三角门禁与全量或分区重索引。增量协议：内容哈希决定重嵌——块文本没变不重嵌（注意：切分边界变了，邻居变了，语义就变，此时必须全量重算）；删除走墓碑，先全通道墓碑、物理删除异步；更新实现为删加写，不做原地改；文档级原子性——同一文档的新块全部就绪才对外可见，否则检索到半新半旧。重建走蓝绿：新索引全量构建、过门禁、切流量、旧的保留回滚窗口；大库全量贵，按文档更新热力分区滚动重建。陈旧性 SLA：从源变更到索引可见的最大时延按查询类型分档，时效型问答要求分钟级，其余小时级即可。</p><p><span class="marginnote">数字实例：文档 10 个块、重写后 3 个块文本没变。按哈希只重嵌 7 个块，省七成嵌入费用——但前提是切分边界没动。若这次升级同时换了切分器，边界挪一格，那 3 个「没变」的块的上下文也全变了，必须全量重算，省的钱一分不能省。</span></p>',9)),(B(),n(s,null,{default:A(()=>[r(l,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20SRC%5B%22%E6%BA%90%E6%96%87%E6%A1%A3%E5%8F%98%E6%9B%B4%22%5D%20--%3E%20HASH%5B%22%E5%86%85%E5%AE%B9%E5%93%88%E5%B8%8C%E6%AF%94%E5%AF%B9%22%5D%0A%20%20HASH%20--%3E%7C%E5%9D%97%E6%96%87%E6%9C%AC%E6%9C%AA%E5%8F%98%7C%20KEEP%5B%22%E4%BF%9D%E7%95%99%E5%9D%97%E4%B8%8E%20ID%22%5D%0A%20%20HASH%20--%3E%7C%E5%8F%98%E6%9B%B4%7C%20RE%5B%22%E5%88%A0%E5%8A%A0%E5%86%99%EF%BC%9A%E5%A2%93%E7%A2%91%20%2B%20%E9%87%8D%E5%B5%8C%22%5D%0A%20%20RE%20--%3E%20ATOM%5B%22%E6%96%87%E6%A1%A3%E7%BA%A7%E5%8E%9F%E5%AD%90%E5%8F%91%E5%B8%83%22%5D%0A%20%20KEEP%20--%3E%20ATOM%0A%20%20ATOM%20--%3E%20SYNC%5B%22%E5%85%A8%E9%80%9A%E9%81%93%E5%90%8C%E6%AD%A5%EF%BC%9A%E5%80%92%E6%8E%92%20%2B%20%E5%90%91%E9%87%8F%20%2B%20%E7%BC%93%E5%AD%98%E5%A4%B1%E6%95%88%22%5D%0A%20%20SYNC%20--%3E%20REBUILD%7B%22%E7%89%88%E6%9C%AC%E4%B8%89%E5%85%83%E7%BB%84%E5%8F%98%E4%BA%86%EF%BC%9F%22%7D%0A%20%20REBUILD%20--%3E%7C%E6%98%AF%7C%20BG%5B%22%E8%93%9D%E7%BB%BF%E9%87%8D%E5%BB%BA%20%2B%20%E4%B8%89%E8%A7%92%E9%97%A8%E7%A6%81%22%5D%0A%20%20REBUILD%20--%3E%7C%E5%90%A6%7C%20LIVE%5B%22%E5%AF%B9%E5%A4%96%E5%8F%AF%E8%A7%81%22%5D%0A%20%20BG%20--%3E%20LIVE%0A"})]),fallback:A(()=>[...E[0]||(E[0]=[a(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=e("h2",{id:"机制",tabindex:"-1"},[a("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=e("p",null,[a("跨通道删除为什么是安全问题：混合检索两路索引独立写入独立删除，删除不同步时，无权限或已撤回的文档从漏掉的一路被召回——检索管道对所有索引到的内容一视同仁地信任，"),e("a",{href:"/llm/retrieval-poisoning-defense"},"投毒防御"),a("的鉴权与隔离必须延伸到更新路径：每条写请求都是注入面。为什么「没变就不重嵌」有例外：晚切分与语义断点的块语义依赖邻域，边界一动邻居全变，哈希相等不等于语义相等。为什么蓝绿比原地改稳：原地改的中间态是一致性黑洞——一半新块一半旧块同时在线，评测与线上都不可复现；蓝绿把中间态关在旧流量背后，门禁过了才见人。")],-1)),(B(),n(s,null,{default:A(()=>[r(l,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20TD%0A%20%20DEL%5B%22%E5%88%A0%E9%99%A4%E5%B7%B2%E6%92%A4%E5%9B%9E%E6%96%87%E6%A1%A3%22%5D%20--%3E%20BM%5B%22%E5%80%92%E6%8E%92%E9%80%9A%E9%81%93%3A%20%E5%88%A0%E9%99%A4%E6%88%90%E5%8A%9F%22%5D%0A%20%20DEL%20--%3E%20VE%5B%22%E5%90%91%E9%87%8F%E9%80%9A%E9%81%93%3A%20%E5%86%99%E5%A4%B1%E8%B4%A5%20%2F%20%E6%BC%8F%E5%88%A0%22%5D%0A%20%20BM%20--%3E%20SAFE%5B%22%E8%AF%8D%E6%B3%95%E6%9F%A5%E8%AF%A2%E5%B7%B2%E6%89%BE%E4%B8%8D%E5%88%B0%22%5D%0A%20%20VE%20--%3E%20LEAK%5B%22%E5%90%91%E9%87%8F%E6%9F%A5%E8%AF%A2%E4%BB%8D%E5%8F%AC%E5%9B%9E%E8%AF%A5%E6%96%87%E6%A1%A3%22%5D%0A%20%20LEAK%20--%3E%20HARM%5B%22%E6%97%A0%E6%9D%83%E9%99%90%20%2F%20%E5%90%88%E8%A7%84%E5%86%85%E5%AE%B9%E6%BC%8F%E5%87%BA%22%5D%0A%20%20SAFE%20--%3E%20FIX%5B%22%E5%AF%B9%E8%B4%A6%E4%BD%9C%E4%B8%9A%E5%8F%91%E7%8E%B0%E5%B9%BD%E7%81%B5%E5%9D%97%22%5D%0A%20%20LEAK%20--%3E%20FIX%0A%20%20FIX%20--%3E%20RULE%5B%22%E5%88%A0%E9%99%A4%E5%BF%85%E9%A1%BB%E5%85%A8%E9%80%9A%E9%81%93%E7%A1%AE%E8%AE%A4%20%2B%20%E5%A2%93%E7%A2%91%E9%87%8D%E8%AF%95%22%5D%0A"})]),fallback:A(()=>[...E[1]||(E[1]=[a(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=t('<p><span class="marginnote">常见误区：初学者容易把跨通道删除失败当成「小事，最多答案旧一点」。错——撤回的合同、下架的政策一旦从另一路被召回，就是合规事故而非质量问题。删除路径要当安全代码写：全通道确认、可重试、有对账。</span></p><p><span class="marginnote">对账作业：定期抽样「索引块回读源文档」，验证块可解析、权限一致、内容存在。「幽灵块率」（源已删、索引还在的比例）是比召回率更容易被忽视的生产指标——它直接对应泄漏与陈旧答案。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>完全一致有代价：同步双写放大写延迟，多数系统选最终一致加墓碑加对账，SLA 写清楚即可，不必假装强一致。金标集随语料换代要重新对齐支撑跨度，与评测课的版本口径联动；缓存失效策略与更新协议同设计——上一课的缓存三层在文档更新时全部要考虑失效，只失效一层会出现「检索新、生成旧」。更新节奏、重建成本与查询陈旧容忍度三方权衡，没有普适答案；失败模式的跨层汇总与排查法，是下一课也是本课程的收束。</p><p><span class="marginnote">为什么重要：只失效检索缓存、忘了失效「答案缓存」或会话记忆，用户会看到检索已经拿到新政策、模型却照着旧缓存回答——两条都对，拼起来自相矛盾。更新协议和缓存失效必须画在同一张时序图里设计。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>版本三元组（切分、嵌入、分析器）加配置版本一体记录，一变即门禁加重索引。</li><li>增量协议：内容哈希重嵌、墓碑先行、删加写、文档级原子发布。</li><li>跨通道删除不同步是安全事故不是陈旧问题；鉴权延伸到更新路径。</li><li>蓝绿重建消灭中间态；大库按更新热力分区滚动。</li><li>幽灵块率进生产指标；金标与缓存随版本联动失效。</li><li>出处：据索引版本化与检索运维实践整理；投毒口径见公开检索投毒研究。</li></ul>',7))])}const u=i(p,[["render",D]]);export{f as __pageData,u as default};
